export function defineSchedule(definition) {
    if (!definition.key || !/^[A-Za-z0-9][A-Za-z0-9._:-]*$/.test(definition.key))
        throw new Error('Schedule key must be a stable identifier.');
    if (!definition.title)
        throw new Error('Schedule title is required.');
    const parts = definition.schedule?.cron?.trim().split(/\s+/) ?? [];
    if (parts.length !== 5 && parts.length !== 6)
        throw new Error('Schedule cron must contain five or six fields.');
    const timezone = definition.schedule.timezone ?? 'UTC';
    try {
        CronExpressionParser.parse(definition.schedule.cron, {
            currentDate: new Date('2020-01-01T00:00:00.000Z'),
            tz: timezone,
        });
    }
    catch {
        throw new Error('Schedule cron or timezone is invalid.');
    }
    if (!definition.target?.type)
        throw new Error('Schedule target type is required.');
    assertNoSensitiveConfig(definition.target.config);
    if (definition.schedule.limit !== undefined &&
        (!Number.isInteger(definition.schedule.limit) ||
            definition.schedule.limit < 1))
        throw new Error('Schedule limit must be a positive integer.');
    if (definition.schedule.from &&
        definition.schedule.to &&
        definition.schedule.from > definition.schedule.to)
        throw new Error('Schedule from must not be after to.');
    const normalized = {
        ...definition,
        schedule: {
            ...definition.schedule,
            cron: definition.schedule.cron.trim(),
            timezone,
        },
    };
    const canonical = stableStringify(normalized);
    return freezeDeep({
        ...normalized,
        definitionHash: createHash('sha256').update(canonical).digest('hex'),
    });
}

async execute() {
    const context = this.context;
    if (!context.scheduleId) {
        throw new Error('ScheduleDispatchJob requires a schedule id in its occurrence context.');
    }
    // The occurrence is identified by the queue's job id alone. Nothing else
    // about the firing is read from the transport, which is what keeps
    // `@boringnode/queue` an unmodified dependency.
    const executionContext = {
        scheduleId: this.payload.scheduleId,
        occurrenceId: context.jobId,
    };
    const targetState = (await this.registry.describe(this.payload.target.type, this.payload.target.config)).state;
    if (targetState && targetState !== 'ready') {
        await this.occurrences.skip(context.jobId, `target-${targetState ?? 'unavailable'}`);
        return;
    }
    const action = await this.occurrences.start(executionContext, this.payload.definitionHash, this.payload.target.type);
    if (action === 'noop')
        return;
    try {
        const result = await this.registry.start(this.payload.target.type, this.payload.target.config, executionContext);
        switch (result.state) {
            case 'completed':
                await this.occurrences.succeed(context.jobId, result.result);
                return;
            case 'accepted': {
                await this.occurrences.wait(context.jobId, result.reference, result.receipt);
                const observation = await this.registry.inspect(this.payload.target.type, result.reference);
                if (observation.state === 'completed')
                    await this.occurrences.complete(context.jobId, result.reference, observation.completion);
                return;
            }
            case 'skipped':
                await this.occurrences.skip(context.jobId, result.reason);
                return;
            case 'failed':
                await this.occurrences.fail(context.jobId, result.reason);
                return;
        }
    }
    catch (error) {
        try {
            await this.occurrences.fail(context.jobId, 'dispatch-failed');
        }
        catch (completionError) {
            console.error('Failed to record schedule dispatch failure', {
                occurrenceId: context.jobId,
                error: completionError,
            });
        }
        throw error;
    }
}

async start(context, definitionHash, targetType) {
    const now = new Date();
    const existing = await this.find(context.occurrenceId);
    if (existing) {
        if (existing.status === 'waiting' || TERMINAL.has(existing.status))
            return 'noop';
        const updated = await this.database
            .query()
            .updateTable('schedule_occurrences')
            .set({
            status: 'running',
            executionCount: existing.executionCount + 1,
            lastStartedAt: now,
            updatedAt: now,
        })
            .where('id', '=', context.occurrenceId)
            .where('status', 'in', ['pending', 'running'])
            .execute();
        if ((updated.updatedCount ?? 0) === 0) {
            const current = await this.required(context.occurrenceId);
            if (current.status === 'waiting' || TERMINAL.has(current.status))
                return 'noop';
        }
        return 'start';
    }
    await this.database
        .query()
        .insertInto('schedule_occurrences')
        .values({
        id: context.occurrenceId,
        scheduleId: context.scheduleId,
        definitionHash,
        status: 'running',
        reason: null,
        targetType,
        targetReferenceType: null,
        targetReferenceId: null,
        targetReceipt: null,
        resultSummary: null,
        executionCount: 1,
        startedAt: now,
        acceptedAt: null,
        lastStartedAt: now,
        lastObservedAt: null,
        finishedAt: null,
        createdAt: now,
        updatedAt: now,
    })
        .execute();
    return 'start';
}

async complete(occurrenceId, reference, completion, 
// Set when the caller holds a handle for one target type, so that
// registering a target grants no power over another target's occurrences.
expectedTargetType) {
    assertReference(reference);
    const existing = await this.required(occurrenceId);
    if (expectedTargetType && existing.targetType !== expectedTargetType)
        throw new ScheduleOccurrenceError('REFERENCE_MISMATCH', `Occurrence "${occurrenceId}" does not belong to target type "${expectedTargetType}"`);
    // A workflow may finish between target.start() returning its run id and
    // wait() persisting that id on the occurrence. The terminal observer is
    // best-effort in that small window; dispatch performs an immediate inspect
    // after wait(), and reconciliation covers any missed notification.
    if (existing.status === 'running' &&
        !existing.targetReferenceType &&
        !existing.targetReferenceId)
        return;
    this.assertMatchingReference(existing, reference);
    if (TERMINAL.has(existing.status)) {
        if (existing.status === completion.status)
            return;
        throw new ScheduleOccurrenceError('COMPLETION_CONFLICT', `Occurrence "${occurrenceId}" is already ${existing.status}`);
    }
    if (existing.status !== 'waiting')
        throw new ScheduleOccurrenceError('INVALID_STATE', `Occurrence "${occurrenceId}" cannot complete from ${existing.status}`);
    await this.finish(occurrenceId, completion.status, completion.reason, completion.result, completion.finishedAt, reference);
}

